tags.description:
createIndividual({
  identifier: [{ system: "urn:openspp:vocab:id-type#national_id", value: "PH-123456789" }],
  name: { family: "Santos", given: "Maria" },
  birthDate: "1985-03-15",
  gender: { coding: [{ system: "urn:iso:std:iso:5218", code: "2" }] },
});

createGroup({
  identifier: [{ system: "urn:openspp:vocab:id-type#household_id", value: "HH-1" }],
  name: "Santos Household",
  groupType: "household",
});

fn(state => {
  // do some things to state
  return state;
});

each(
  $.data,
  // Inside the callback operation, `$.data` is scoped to the item under iteration
  insert("patient", {
    patient_name: $.data.properties.case_name,
    patient_id: $.data.case_id,
  })
);

each(
  "$.data[*]",
  insert("patient", (state) => ({
    patient_name: state.data.properties.case_name,
    patient_id: state.data.case_id,
  }))
);
